mapper.select:
SELECT FROM device WHERE status = 'ONLINE' AND deleted = 0
AND owner_id = #{ownerId}
ORDER BY last_seen DESC

SELECT d.id, d.device_name, d.device_key, d.device_type, d.topic, d.description, d.owner_id, d.status, d.last_seen, d.metadata, d.created_at, d.updated_at, u.username AS owner_username FROM device d LEFT JOIN sys_user u ON d.owner_id = u.id WHERE d.deleted = 0
AND d.owner_id = #{dto.ownerId}
AND d.device_name LIKE CONCAT('%', #{dto.deviceName}, '%')
AND d.device_type = #{dto.deviceType}
AND d.status = #{dto.status}
ORDER BY d.created_at DESC
